using System;

namespace ZeroGraphics.Waveform.Pipeline.Shaders
{
    /// <summary>
    /// Precompiled HLSL shader bytecode for real-time oscilloscope line-strip rendering.
    /// </summary>
    public static class WaveformBytecodes
    {
        private static readonly Lazy<byte[]> _vsBytecode = new Lazy<byte[]>(() =>
            Convert.FromBase64String(""));

        private static readonly Lazy<byte[]> _psBytecode = new Lazy<byte[]>(() =>
            Convert.FromBase64String(""));

        public static byte[] WaveformVertexShaderBytecode => _vsBytecode.Value;
        public static byte[] WaveformPixelShaderBytecode => _psBytecode.Value;
    }
}